// Notification gate. Never sends; only decides.
// Rules: requested + reminder always pass (the user asked for them).
// Inferred nudges: held for NEW_USER_MS after the account/profile start,
// then limited to config.dailyNudgeCap per recipient-local day.
const NEW_USER_MS = 24 * 3600 * 1000;

export const REASON_CODES = [
  'new_user_grace',
  'daily_cap_reached',
  'timezone_unknown',
  'user_age_unknown',
  'cap_unknown',
  'origin_unknown',
  'input_incomplete',
];

const hold = (reasonCode) => ({ send: false, reasonCode });

export async function decide({ user, candidate, now, config } = {}) {
  const dir = process.env.STATE_DIR;
  if (!dir) return hold('input_incomplete');
  gkFs.mkdirSync(dir, { recursive: true });
  if (!user || !candidate || user.id == null || candidate.id == null) return hold('input_incomplete');
  const ms = now instanceof Date ? now.getTime() : Number(now);
  if (!Number.isFinite(ms)) return hold('input_incomplete');

  const origin = candidate.origin;
  if (origin !== 'requested' && origin !== 'reminder' && origin !== 'inferred') return hold('origin_unknown');

  const uid = encodeURIComponent(String(user.id));
  const sentKey = `sent-${uid}-${encodeURIComponent(String(candidate.id))}`;

  // Same message id: same answer, nothing spent twice.
  if (gkRead(dir, sentKey)) return { send: true, reasonCode: null };

  if (origin === 'inferred') {
    // Newest known start of the relationship; an unreadable date is unknown, so hold.
    const starts = [user.createdAt, user.profileCreatedAt].map((d) => Date.parse(d));
    if (starts.some((t) => !Number.isFinite(t))) return hold('user_age_unknown');
    if (ms < Math.max(...starts) + NEW_USER_MS) return hold('new_user_grace');

    const cap = config && config.dailyNudgeCap;
    if (!Number.isInteger(cap) || cap < 0) return hold('cap_unknown');
    if (typeof user.timezone !== 'string' || !gkZoneOk(user.timezone)) return hold('timezone_unknown');
    if (cap === 0) return hold('daily_cap_reached');

    if (!gkClaim(dir, sentKey + '.claim')) {
      // Another worker is deciding/has decided this id.
      return gkRead(dir, sentKey) ? { send: true, reasonCode: null } : hold('daily_cap_reached');
    }
    const dayKey = `nudge-${uid}-${gkDayKey(ms, user.timezone)}`;
    const c = gkCount(dir, dayKey, cap);
    if (!c.ok) {
      gkUnclaim(dir, sentKey + '.claim');
      return hold('daily_cap_reached');
    }
    gkWrite(dir, sentKey, { at: ms });
    return { send: true, reasonCode: null };
  }

  // requested / reminder: claim once, no cap, no quiet hours (none stated).
  if (gkClaim(dir, sentKey + '.claim')) gkWrite(dir, sentKey, { at: ms });
  return { send: true, reasonCode: null };
}
EOF
